CREATE TABLE IF NOT EXISTS equipment_maintenance (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), asset_id uuid NOT NULL REFERENCES equipment_assets(id), event_type text NOT NULL, description text NOT NULL, cost_rub numeric(12,2), performed_at date NOT NULL DEFAULT CURRENT_DATE, next_due_at date, created_by uuid REFERENCES service_employees(id), created_at timestamptz NOT NULL DEFAULT now());
